"""Source-derived arithmetic and NEW scoped-rule specifications only."""
import unittest,copy,math,json
from pathlib import Path
from reference_rules import *
O=Path(__file__).resolve().parents[1]
class Echo(unittest.TestCase):
 def test_inclusive18(self):self.assertTrue(legal_original(age=18,resolved=True,observed=True,rank=3))
 def test_expired18_001(self):self.assertFalse(legal_original(age=18.001,resolved=True,observed=True,rank=3))
 def test_no_rank7_gate(self):self.assertTrue(legal_original(age=1,resolved=True,observed=True,rank=9))
 def test_countered_not_original(self):self.assertFalse(legal_original(age=1,resolved=False,observed=True,rank=3))
 def test_unobserved_not_original(self):self.assertFalse(legal_original(age=1,resolved=True,observed=False,rank=3))
 def test_descended_exclusion_explicit(self):self.assertFalse(legal_original(age=1,resolved=True,observed=True,rank=3,descended=True))
 def test_wrapper_exclusion_explicit(self):self.assertFalse(legal_original(age=1,resolved=True,observed=True,rank=7,wrapper=True))
 def test_two_prices(self):self.assertEqual(echo_forecast(48,0,3),{'outer':17,'child':5,'outerD':0,'remaining':26})
 def test_child_rank9_price_not_payload_evidence(self):self.assertEqual(echo_forecast(48,0,9)['remaining'],5)
 def test_strain_reprice(self):self.assertEqual(echo_forecast(48,9,3,outer_first=False),{'outer':17,'child':6,'outerD':11,'remaining':25})
 def test_known_combined_shortfall(self):self.assertRaises(ValueError,echo_forecast,21,0,3)
 def test_outercounter_retains_only_outer(self):self.assertEqual(complete_outer(48,echo_forecast(48,0,3),True),{'rp':31,'childReservation':0,'childCommitted':False})
 def test_late_child_block_no_refund(self):self.assertEqual(commit_child(31,0,3,blocked=True),{'rp':31,'committed':False})
 def test_child_counter_keeps_both_payments(self):self.assertEqual(commit_child(31,0,3)['rp'],26)
 def test_long_child_not_compressed(self):self.assertEqual(long_completion(2,600),602)
 def test_long_work_break(self):self.assertIsNone(long_completion(2,600,work_continuous=False))
 def test_long_concentration_loss(self):self.assertIsNone(long_completion(2,600,concentration=False))
 def args(self):return dict(reaction=True,concentration=True,source_legal=True,target_legal=True,perceived_trigger=True)
 def test_ready_native_window(self):self.assertTrue(ready_release(3.1,6,child_kind='Reaction',native_window=True,trigger_completed=False,**self.args()))
 def test_ordinary_ready_no_midwindow(self):self.assertFalse(ready_release(3.1,6,trigger_completed=False,**self.args()))
 def test_reaction_needs_native_window(self):self.assertFalse(ready_release(3.1,6,child_kind='Reaction',native_window=False,**self.args()))
 def test_ready_expiry_wins(self):self.assertFalse(ready_release(6,6,**self.args()))
 def test_ready_real_reaction(self):a=self.args();a['reaction']=False;self.assertFalse(ready_release(3,6,**a))
 def test_ready_actual_concentration(self):a=self.args();a['concentration']=False;self.assertFalse(ready_release(3,6,**a))
 def test_ready_current_target(self):a=self.args();a['target_legal']=False;self.assertFalse(ready_release(3,6,**a))
 def test_task_counter(self):self.assertTrue(task_success(8,9,16));self.assertTrue(task_success(16,9,24))
class Meta(unittest.TestCase):
 def test_zero_class_use_is_waived_not_refilled(self):self.assertEqual(meta_commit(acquired=True,available=0,active_surge=True,spell_price=5),{'spellCost':5,'remaining':0,'waivedAtCommitment':True})
 def test_zero_adept_point_same_local_exception(self):self.assertEqual(meta_commit(acquired=True,available=0,active_surge=True)['remaining'],0)
 def test_no_acquisition(self):self.assertRaises(ValueError,meta_commit,acquired=False,available=0,active_surge=True)
 def test_expiry_exhausted_source(self):self.assertRaises(ValueError,meta_commit,acquired=True,available=0,active_surge=False)
 def test_suppression_new_commit(self):self.assertRaises(ValueError,meta_commit,acquired=True,available=0,active_surge=False)
 def test_one_mode(self):self.assertRaises(ValueError,meta_commit,acquired=True,available=1,active_surge=True,mode_count=2)
 def test_spell_price_not_waived(self):self.assertEqual(meta_commit(acquired=True,available=1,active_surge=True,spell_price=17)['spellCost'],17)
 def test_ordinary_source_still_spends(self):self.assertEqual(meta_commit(acquired=True,available=1,active_surge=False)['remaining'],0)
 def test_ready_lock_no_repricing(self):r=meta_commit(acquired=True,available=0,active_surge=True);self.assertTrue(r['waivedAtCommitment']);self.assertEqual(r['remaining'],0)
class MemoryAndBody(unittest.TestCase):
 def test_erase_direct(self):self.assertFalse(erase_select(active=True,direct_new=True))
 def test_erase_area(self):self.assertTrue(erase_select(active=True,direct_new=False,area=True))
 def test_erase_existing(self):self.assertTrue(erase_select(active=True,direct_new=True,existing=True))
 def test_erase_suppressed(self):self.assertTrue(erase_select(active=False,direct_new=True))
 def test_observer_bounds(self):p={'near':dict(distance=120,los=True,perceived=True),'wall':dict(distance=5,los=False,perceived=True),'far':dict(distance=121,los=True,perceived=True),'subject':dict(distance=0,los=True,perceived=True)};s={k:{'old':{'subject':'subject'}} for k in p};self.assertEqual(masks_for(s,'subject',p),{'near':{'old'}})
 def test_new_memory_kept_and_real_deletion_not_undone(self):ep={'old':{'subject':'s'},'new':{'subject':'s'}};self.assertEqual(set(source_mask_end(ep,{'erase':{'old','deleted'}},'erase')),{'old','new'})
 def test_other_mask_survives(self):ep={'old':{'subject':'s'},'new':{'subject':'s'}};self.assertEqual(set(source_mask_end(ep,{'a':{'old'},'b':{'old'}},'a')),{'new'})
 def test_two_medium_bodies_contact_not_overlap(self):self.assertFalse(body_interiors_overlap([0,0,0],[5,0,0]))
 def test_real_body_overlap(self):self.assertTrue(body_interiors_overlap([0,0,0],[4.9,0,0]))
 def test_carrying_real_body_burdened_threshold(self):self.assertEqual(carrying(180,7,14),20)
 def test_weight_and_load_independent(self):self.assertRaises(ValueError,carrying,211,7,14);self.assertRaises(ValueError,carrying,100,15,14)
class Suspension(unittest.TestCase):
 def test_positive_consented_admission(self):self.assertTrue(seq_admit(2.1,20,True,True))
 def test_hard_guard_not_willing_bypass(self):self.assertFalse(seq_admit(2.1,20,True,False))
 def test_suspension_immune_no_partial_invis(self):self.assertFalse(seq_admit(2.1,20,True,True,True))
 def test_no_infinite_deadline(self):self.assertFalse(seq_admit(2.1,math.inf,True,True))
 def test_deadline_must_be_future(self):self.assertFalse(seq_admit(2.1,2.1,True,True))
 def test_no_forced_consent(self):self.assertFalse(seq_admit(2.1,20,False,True))
 def test_bio_pauses_source_time_runs(self):r=suspension_advance({'age':100,'breath':30},5,4.3);self.assertEqual(r,{'bio':{'age':100,'breath':30},'worldElapsed':5,'sourceRemaining':0,'restCredit':0})
 def test_positive_pretemp_wakes(self):self.assertEqual(seq_damage(24,5,4),{'hp':24,'temp':1,'awake':True,'damageEvent':4})
 def test_zero_packet_does_not_wake(self):self.assertFalse(seq_damage(24,5,0)['awake'])
 def test_real_hp_damage_wakes(self):self.assertEqual(seq_damage(20,0,6)['hp'],14)
class Duplicate(unittest.TestCase):
 def acct(self):return {'rp':6,'maxRp':48,'d':4,'cooldown':0,'last':'ray','refrain':1,'used':{'ray'}}
 def donor(self):return {'actualDead':False,'hp':52,'maxHp':80,'size':'Medium','mass':170,'wounds':0,'critical':False,'injury':[],'rp':48,'temporaryHP':9,'concentration':'external'}
 def test_self_copy_after_real_payment(self):d=self.donor();r=create_body(d,31,self_copy=True);self.assertEqual((r['hp'],r['rp']),(52,31));self.assertEqual(d['rp'],48)
 def test_no_foreign_half_stats(self):self.assertEqual(create_body(self.donor(),31)['maxHp'],80)
 def test_no_external_temp_or_concentration(self):r=create_body(self.donor(),31);self.assertEqual(r['temporaryHP'],0);self.assertIsNone(r['concentration'])
 def test_actual_dead_is_not_creature(self):d=self.donor();d['actualDead']=True;self.assertIsNone(create_body(d,31))
 def test_zero_hp_no_live_replacement(self):d=self.donor();d['hp']=0;r=create_body(d,31);self.assertFalse(r['liveReplacement']);self.assertFalse(r['loot'])
 def test_failed_replacement_keeps_old(self):old={'liveReplacement':True,'hp':30};self.assertIs(replacement(old,{'liveReplacement':False}),old)
 def test_first_account_current_not_full(self):r=derivative_account('a','b',self.acct());self.assertEqual(r['rp'],6)
 def test_recast_no_resource_refill(self):a=self.acct();old=copy.deepcopy(a);old['rp']=5;old['last']='resonance-shield';old['refrain']=0;r=derivative_account('a','b',a,old);self.assertEqual((r['rp'],r['last'],r['refrain']),(5,'resonance-shield',0))
 def test_donor_shortfall_can_reduce(self):a=self.acct();old=copy.deepcopy(a);a['rp']=2;self.assertEqual(derivative_account('a','b',a,old)['rp'],2)
 def test_lower_current_max_clamps(self):a=self.acct();old=copy.deepcopy(a);a['maxRp']=3;self.assertEqual(derivative_account('a','b',a,old)['rp'],3)
 def test_recast_debt_does_not_clear(self):a=self.acct();old=copy.deepcopy(a);a['d']=2;self.assertEqual(derivative_account('a','b',a,old)['d'],4)
 def test_used_history_union(self):a=self.acct();old=copy.deepcopy(a);old['used']={'shield'};self.assertEqual(derivative_account('a','b',a,old)['used'],{'ray','shield'})
 def test_lineage_not_bodyid(self):r=derivative_account('a','b',self.acct());self.assertEqual(r['key'],('a','b'))
 def test_original_not_debited(self):a=self.acct();r=derivative_account('a','b',a);r['rp']-=1;self.assertEqual(a['rp'],6)
 def test_absence_no_rest(self):a=self.acct();r=active_rest(a,active=False,safe=True,supplied=True,beneficial_budget=True,hours=8);self.assertEqual(r['rp'],6)
 def test_true_active_rest_can_recover(self):a=self.acct();r=active_rest(a,active=True,safe=True,supplied=True,beneficial_budget=True,hours=8);self.assertEqual((r['rp'],r['d'],r['last']),(48,0,None))
 def test_no_double_rest_allowance(self):r=active_rest(self.acct(),active=True,safe=True,supplied=True,beneficial_budget=False,hours=8);self.assertEqual(r['rp'],6)
 def test_projectile_positive_native_attack(self):r=projectile(3,lawful=True);self.assertEqual(r['ammo'],2);self.assertTrue(r['existsThroughResolution']);self.assertFalse(r['recoverable'])
 def test_prop_transfer_not_money_or_ammo(self):r=projectile(3,lawful=True,offered_for_transfer=True);self.assertFalse(r['exists']);self.assertFalse(r['attack'])
 def test_no_empty_ammo_attack(self):self.assertFalse(projectile(0,lawful=True)['attack'])
class CompleteFixtures(unittest.TestCase):
 @classmethod
 def setUpClass(cls):cls.cases=json.loads((O/'CASE_DISPOSITIONS.json').read_bytes())['cases']
 def test_echo_actual_shared_dice(self):c=self.cases[0];self.assertEqual(sum(c['timeline'][-1]['rng']['shared8d6']),28);self.assertEqual(c['expectedFinalState']['actors']['newTarget']['hp'],52);self.assertEqual(c['expectedFinalState']['actors']['echoer']['hp'],66)
 def test_original_fireball_self_half(self):c=self.cases[0];self.assertEqual(c['expectedFinalState']['actors']['donor']['hp'],68)
 def test_counter_child_complete(self):c=self.cases[1];self.assertEqual(c['expectedFinalState']['actors']['echoer']['rp'],26);self.assertFalse(c['expectedFinalState']['actors']['echoer']['reaction']);self.assertEqual(c['expectedFinalState']['actors']['enemy']['dissonance'],2)
 def test_meta_repeat_and_idle(self):c=self.cases[2];self.assertEqual(c['expectedFinalState']['actors']['target']['hp'],69);self.assertEqual(c['expectedFinalState']['actors']['mage']['dissonance'],0)
 def test_sculpt_real_damage(self):c=self.cases[3];self.assertEqual(c['expectedFinalState']['actors']['foe']['hp'],52);self.assertEqual(c['expectedFinalState']['actors']['mage']['hp'],80)
 def test_erase_area_actual(self):c=self.cases[4];self.assertEqual(c['expectedFinalState']['actors']['protected']['hp'],52);self.assertEqual(c['expectedFinalState']['actors']['attacker']['rp'],43)
 def test_independent_memory_edit(self):c=self.cases[5];self.assertEqual(c['conclusions']['deletedRemains'],['recent']);self.assertEqual(c['conclusions']['observerRecall'],['old'])
 def test_seq_positive_wake(self):c=self.cases[6];self.assertEqual(c['expectedFinalState']['actors']['patient']['hp'],14);self.assertEqual(c['expectedFinalState']['actors']['enemy']['rp'],35);self.assertEqual(c['conclusions']['biologyPausedSeconds'],5)
 def test_seq_carry_clock(self):c=self.cases[7];self.assertEqual(c['expectedFinalState']['actors']['patient']['position'],[20,0,0]);self.assertEqual(c['conclusions']['wake'],20)
 def test_duplicate_actual_spell(self):c=self.cases[8];self.assertEqual(c['expectedFinalState']['actors']['foe']['hp'],74);self.assertEqual(c['expectedFinalState']['objects']['duplicate']['rp'],31)
 def test_duplicate_resource_history_recast(self):c=self.cases[9];self.assertEqual(c['expectedFinalState']['objects']['duplicate']['rp'],5);self.assertEqual(c['expectedFinalState']['actors']['creator']['rp'],14);self.assertEqual(c['expectedFinalState']['actors']['creator']['dissonance'],3);self.assertEqual(c['expectedFinalState']['actors']['donor']['dissonance'],2)
class ActualClassSpellMode(unittest.TestCase):
 def test_ordinary_counter_keeps5(self):self.assertEqual(exact_mode_quote(3,0),5)
 def test_genuine_class_counter_printed3_replaces_rank1base2(self):self.assertEqual(exact_mode_quote(1,0,replacement_price=3,actual_class_entitlement=True),3)
 def test_class_entitlement_not_copied(self):self.assertRaises(ValueError,exact_mode_quote,1,0,replacement_price=3,actual_class_entitlement=False)
 def test_class_recharge_still_required(self):self.assertRaises(ValueError,exact_mode_quote,1,0,replacement_price=3,actual_class_entitlement=True,recharge=1)
 def test_surcharge_not_waived_by_replacement(self):self.assertEqual(exact_mode_quote(1,11,replacement_price=3,actual_class_entitlement=True),4)
 def test_complete_class_mode_example(self):cs=json.loads((O/'CASE_DISPOSITIONS.json').read_bytes())['cases'];b=next(x for x in cs[1]['independentBranches'] if x['id']=='RIC5-01-B-f');a=b['expectedFinalState']['actors']['echoer'];self.assertEqual((a['rp'],a['dissonance'],a['counterRecharge'],a['reaction']),(28,1,2,False))

